import type { Laptop } from '@/types/laptop';

const laptops: Laptop[] = laptopsData as Laptop[];

export function getAllLaptops(): Laptop[] {
  return laptops;
}

export function getLaptopBySlug(slug: string): Laptop | undefined {
  return laptops.find((l) => l.slug === slug);
}

export function getLaptopsByBrand(brand: string): Laptop[] {
  return laptops.filter((l) => l.brand === brand);
}

export function getLaptopsByCpuSeries(cpuSeries: string): Laptop[] {
  return laptops.filter((l) => l.cpu_series === cpuSeries);
}

export function getLaptopsByUseCase(useCase: string): Laptop[] {
  return laptops.filter((l) => l.use_cases.includes(useCase));
}

export function getAllBrands(): string[] {
  return [...new Set(laptops.map((l) => l.brand))].sort();
}

export function getAllCpuSeries(): string[] {
  return [...new Set(laptops.map((l) => l.cpu_series))].sort();
}

export function getAllUseCases(): string[] {
  const all = laptops.flatMap((l) => l.use_cases);
  return [...new Set(all)].sort();
}

export function getComparePairs(limit = 100): [Laptop, Laptop][] {
  const pairs: [Laptop, Laptop][] = [];
  for (let i = 0; i < laptops.length; i++) {
    for (let j = i + 1; j < laptops.length; j++) {
      pairs.push([laptops[i], laptops[j]]);
      if (pairs.length >= limit) return pairs;
    }
  }
  return pairs;
}

export function formatPrice(priceKrw: number): string {
  return new Intl.NumberFormat('ko-KR', {
    style: 'currency',
    currency: 'KRW',
    maximumFractionDigits: 0,
  }).format(priceKrw);
}
