{"type":"assistant","message":{"model":"claude-sonnet-4-6","id":"msg_01842YkGg4XQ6aJvAb1GfcmT","type":"message","role":"assistant","content":[{"type":"tool_use","id":"toolu_01LP7TH1VkX3KawBkk9iA8gq","name":"Write","input":{"file_path":"C:/Users/LG/.paperclip/instances/default/projects/f9ae612a-9e7b-4afb-b00d-6c36a537fd8f/cf4d2a7b-977e-43dd-be73-2d6a54a9ffc6/laptopfyi/app/laptops/[slug]/page.tsx","content":"import { notFound } from 'next/navigation';
import type { Metadata } from 'next';
import { getAllLaptops, getLaptopBySlug, formatPrice } from '@/lib/data';

interface Props {
  params: Promise<{ slug: string }>;
}

export async function generateStaticParams() {
  const laptops = getAllLaptops();
  return laptops.map((l) => ({ slug: l.slug }));
}

export async function generateMetadata({ params }: Props): Promise<Metadata> {
  const { slug } = await params;
  const laptop = getLaptopBySlug(slug);
  if (!laptop) return {};
  return {
    title: laptop.meta_title,
    description: laptop.meta_description,
  };
}

export default async function LaptopPage({ params }: Props) {
  const { slug } = await params;
  const laptop = getLaptopBySlug(slug);
  if (!laptop) notFound();

  const jsonLd = {
    '@context': 'https://schema.org',
    '@type': 'Product',
    name: `${laptop.brand} ${laptop.model}`,
    description: laptop.meta_description,
    brand: { '@type': 'Brand', name: laptop.brand },
    offers: {
      '@type': 'Offer',
      price: laptop.price_krw,
      priceCurrency: 'KRW',
      url: laptop.refurlab_url,
      availability: 'https://schema.org/InStock',
    },
  };

  return (
    <>
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(jsonLd) }}
      />
      <main className="max-w-4xl mx-auto px-4 py-8">
        <h1 className="text-3xl font-bold mb-2">
          {laptop.brand} {laptop.model}
        </h1>
        <p className="text-gray-500 mb-6">{laptop.year}년형</p>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
          <section className="bg-white rounded-xl shadow p-6">
            <h2 className="text-xl font-semibold mb-4">핵심 스펙</h2>
            <dl className="space-y-2 text-sm">
              <div className="flex justify-between">
                <dt className="text-gray-500">CPU</dt>
                <dd className="font-medium">{laptop.cpu}</dd>
              </div>
              <div className="flex justify-between">
                <dt className="text-gray-500">RAM</dt>
                <dd className="font-medium">{laptop.ram_gb}GB</dd>
              </div>
              <div className="flex justify-between">
                <dt className="text-gray-500">스토리지</dt>
                <dd className="font-medium">{laptop.storage_gb}GB {laptop.storage_type}</dd>
              </div>
              <div className="flex justify-between">
                <dt className="text-gray-500">디스플레이</dt>
                <dd className="font-medium">{laptop.display_inch}&quot; {laptop.display_type} {laptop.display_resolution}</dd>
              </div>
              <div className="flex justify-between">
                <dt className="text-gray-500">GPU</dt>
                <dd className="font-medium">{laptop.gpu}</dd>
              </div>
              <div className="flex justify-between">
                <dt className="text-gray-500">배터리</dt>
                <dd className="font-medium">{laptop.battery_wh}Wh</dd>
              </div>
              <div className="flex justify-between">
                <dt className="text-gray-500">무게</dt>
                <dd className="font-medium">{laptop.weight_kg}kg</dd>
              </div>
              <div className="flex justify-between">
                <dt className="text-gray-500">운영체제</dt>
                <dd className="font-medium">{laptop.os}</dd>
              </div>
            </dl>
          </section>

          <section className="bg-blue-50 rounded-xl p-6 flex flex-col justify-between">
            <div>
              <h2 className="text-xl font-semibold mb-2">리퍼랩에서 구매</h2>
              <p className="text-gray-600 text-sm mb-4">
                인증된 리퍼비시 노트북으로 합리적인 가격에 구매하세요.
              </p>
              <p className="text-2xl font-bold text-blue-700 mb-4">
                {formatPrice(laptop.price_krw)}~
              </p>
            </div>
            <a
              href={laptop.refurlab_url}
              target="_blank"
              rel="noopener noreferrer"
              className="bg-blue-600 text-white text-center py-3 rounded-lg font-semibold hover:bg-blue-700 transition-colors"
            >
              리퍼랩에서 보기 →
            </a>
          </section>
        </div>

        <section className="mb-6">
          <h2 className="text-lg font-semibold mb-3">추천 용도</h2>
          <div className="flex flex-wrap gap-2">
            {laptop.use_cases.map((uc) => (
              <a
                key={uc}
                href={`/use-case/${uc}`}
                className="bg-gray-100 text-gray-700 px-3 py-1 rounded-full text-sm hover:bg-gray-200"
              >
                {uc}
              </a>
            ))}
          </div>
        </section>

        <section>
          <h2 className="text-lg font-semibold mb-3">태그</h2>
          <div className="flex flex-wrap gap-2">
            {laptop.tags.map((tag) => (
              <span
                key={tag}
                className="bg-blue-50 text-blue-700 px-3 py-1 rounded-full text-sm"
              >
                #{tag}
              </span>
            ))}
          </div>
        </section>
      </main>
    </>
  );
}
