import type { Metadata } from 'next';
import Link from 'next/link';
import { getAllBrands, getLaptopsByBrand, formatPrice } from '@/lib/data';

interface Props {
  params: Promise<{ slug: string }>;
}

export async function generateStaticParams() {
  return getAllBrands().map((brand) => ({ slug: brand }));
}

const BRAND_NAMES: Record<string, string> = {
  samsung: '삼성',
  lg: 'LG',
  apple: '애플',
  asus: 'ASUS',
  lenovo: '레노버',
  hp: 'HP',
  dell: '델',
  acer: '에이서',
  microsoft: '마이크로소프트',
};

