  const { slug } = await params;
  const name = BRAND_NAMES[slug] ?? slug.toUpperCase();
  return {
    title: `${name} 노트북 전체 라인업 | LaptopFYI`,
    description: `${name} 노트북 전체 모델 스펙, 가격 비교. 리퍼랩 최저가 구매 링크 제공.`,
  };
}

