  const laptops = getLaptopsByBrand(slug);
  if (laptops.length === 0) notFound();

  const brandName = BRAND_NAMES[slug] ?? slug.toUpperCase();

  return (
    <main className="max-w-4xl mx-auto px-4 py-8">
      <h1 className="text-3xl font-bold mb-2">{brandName} 노트북</h1>
      <p className="text-gray-500 mb-8">전체 {laptops.length}개 모델</p>

      <div className="grid gap-4">
        {laptops.map((laptop) => (
          <div key={laptop.slug} className="bg-white rounded-xl shadow p-5 flex justify-between items-center">
            <div>
              <Link
                href={`/laptops/${laptop.slug}`}
                className="text-lg font-semibold hover:text-blue-600"
              >
                {laptop.model}
              </Link>
              <p className="text-sm text-gray-500 mt-1">
                {laptop.cpu} · {laptop.ram_gb}GB · {laptop.storage_gb}GB {laptop.storage_type} · {laptop.display_inch}&quot; {laptop.display_type}
              </p>
            </div>
            <div className="text-right">
              <p className="font-bold text-blue-700">{formatPrice(laptop.price_krw)}~</p>
              <a
                href={laptop.refurlab_url}
                target="_blank"
                rel="noopener noreferrer"
                className="text-sm text-blue-500 hover:underline"
              >
                리퍼랩 →
              </a>
            </div>
          </div>
        ))}
      </div>
    </main>
  );
}
